import 'enemy_type.dart'; import 'enemy_stats.dart'; import 'enemy_abilities.dart';
class EnemyRuntimeState { final EnemyTypeData type; final EnemyStats stats; double abilityCooldown=0; bool isDefeated=false; EnemyAbility? nextAbility; EnemyRuntimeState(this.type,{required int floor,required double difficulty}):stats=EnemyStats.forType(type,floor:floor,difficulty:difficulty); EnemyAbilityData prepareAbility(EnemyAbility id){nextAbility=id;abilityCooldown=EnemyAbilityData.all[id]!.cooldown;return EnemyAbilityData.all[id]!;} void update(double dt){abilityCooldown=(abilityCooldown-dt).clamp(0,999).toDouble();} }
